// Import validationResult from express-validator.
const { validationResult } = require("express-validator");

// Middleware to check the results of validation rules.
const validate = (req, res, next) => {
    // Collect validation errors generated by the validator.
    const errors = validationResult(req);

    // If validation errors exist, forward them to errorHandler.
    if (!errors.isEmpty()) {
        return res.status(400).json({
            success: false,
            message: "Validation failed",
            errors: errors.array().map((error) => ({
                field: error.path,
                message: error.msg,
            })),
        });
    }

    // If there are no errors, continue to the next middleware.
    next();
};

// Export the middleware.
module.exports = validate;